/**
 * Formats a timestamp in milliseconds.
 * Returns the time (hhmm) if the date is today, or the date (DD/MM/YYYY) if it's not today.
 *
 * @param {number} timestampMs - The datetime in milliseconds.
 * @returns {string} The formatted time or date string.
 */
const formatTimeOrDate = (timestampMs) => {
    // 1. Create Date objects for the given timestamp and the current time
    const inputDate = new Date(timestampMs);
    const today = new Date();

    // 2. Helper function to check if a date is today
    // We compare the year, month, and day of the month.
    const isToday = (date) => {
        return date.getFullYear() === today.getFullYear() &&
            date.getMonth() === today.getMonth() &&
            date.getDate() === today.getDate();
    };

    // 3. Format components with leading zeros
    const pad = (num) => String(num).padStart(2, '0');

    if (isToday(inputDate)) {
        // Return time in hhmm format (e.g., 1435)
        const hours = pad(inputDate.getHours());
        const minutes = pad(inputDate.getMinutes());
        return `${hours}:${minutes}`; // 

    } else {
        // Return date in DD/MM/YYYY format (e.g., 25/11/2025)
        const day = pad(inputDate.getDate());
        const monthName = inputDate.toLocaleString('default', { month: 'short' });
        return `${monthName} ${day}`; // 
    }
};


const utils =
{
    square:((a) =>  a * a),

    oneDecPoint : (n) => (Math.round(n * 10) / 10),
    twoDecPoint : (n) => (Math.round(n * 100) / 100),
    //toFix : (num, precision) => (Math.trunc(num * (10 ** precision))) / (10 ** precision),
    toFix: (num, precision) => (Math.round(num * (10 ** precision))) / (10 ** precision),

    getHHMM: (millis) => new Date(millis).toTimeString().substring(0, 5),
    getHHMMSS: (millis) => new Date(millis).toTimeString().substring(0, 8),

    getHHMMNow: () => utils.getHHMM(Date.now()),
    getHHMMSSNow: () => utils.getHHMMSS(Date.now()),

    getTimeNow: () => utils.getHHMM(Date.now()),

    getTimeOrDate: (millis) => formatTimeOrDate(millis),
    getTimeOrDateNow: () => formatTimeOrDate(Date.now()),

    isTimedOut: (last_seen, timeNow, minutes = 60) => timeNow > last_seen + 1000 * 60 * minutes, 

    sensorStatus: (sensorsKnown, instruments, minutes, timeNow) => 
    {
        const isTimedOut = (name) => 
            utils.isTimedOut(instruments[name + '/temperature'].timestamp, timeNow, minutes)

        const sensorsActive = Object.keys(instruments)
            .filter((s) => s.split('/')[1] == 'temperature')
            .map((s) => s.split('/')[0])

        const neverSeen = sensorsKnown
            .filter((name) => !sensorsActive.includes(name))

        const timedOut2 = sensorsActive
            .filter((name) => sensorsActive.includes(name))
            .filter((name) => isTimedOut(name))

        const timedOut = sensorsActive
            .filter((name) => sensorsActive.includes(name))
            .filter((name) => isTimedOut(name))
            .map((name) => name + ':'
                + utils.getHHMM(instruments[name + '/temperature'].timestamp ?? 0))

        const online = sensorsActive
            .filter((name) => (!isTimedOut(name)))

        return { online: online, timedOut: timedOut, timedOut2: timedOut2,  neverSeen: neverSeen }
    }

}
