      break;

    case 'sensor0/get/siteConfig' :
      const mout = {
        topic:  replyTopic,
        payload: siteConfig
      }
      updateMQTT.push(mout);
      break       

    case 'sensor0/get/online':
    case 'sensor0/get/neverSeen':
    case 'sensor0/get/timedOut':

      const sensorsKnown = Object.keys(siteConfig['sensorMap'])
      const res = utils.sensorStatus(sensorsKnown, instrumentation, 29, timeNow)
      const n = {
