      nodeStatus = { fill: "green", shape: "dot", text: `cleared ${ar2.length} items` };
      clearProperties(instrumentation);
      flow.set("instrumentation", instrumentation);
      break;

    case 'availability':
      const m = instrumentation[msg.topic]
      m.state = msg.payload;
      updateDashboard.push(m)
      updateMQTT.push(m)
      break;

    default:
      if (msg.topic.startsWith('sensor0'))   // suppress echo of sensor0 output!
        break 
      //nodeStatus = { fill: "red", shape: "dot", text: `mirrored ${msg.topic} ${msg.payload}` };
      if (isSensorMessage(msg)) {
