/**
 * Initially generated by Claude
 * 
 * Optimum start time (hours, same clock as dtOpen).
 * p.dtOpen   building opening time (unix)
 * p.hsp      heating set point temp (°C)
 * p.spt      indoor space temp when heating switched off (°C)
 * p.capacity thermal capacity (kWh/°C)
 * p.power    boiler output (kW)
 * p.loss     heat loss (kW) per °C
 * dtStart    time heating switched off (unix)
 * oatFn      function(t) -> outside temp (°C)
 * dtStep     step size in secs (360 = 6 min)
 */


function startTime(prop, dtStart, oatFn, tChart, dtStep = 15 * 60) {
  const dtH = dtStep / 3600; // step in hours, since C, P, L are kWh/kW based

  // Forward passive cooling curve from switch-off to opening

  let dt = dtStart;
  let spt = prop.spt;
  let n = 1000  // stop node-red from crashing if there's an infinite loop

  const coolT = [];
  const coolTemp = [];
  while (dt < prop.dtOpen && n) {
    const oat = oatFn(dt)
    spt += (dtH / prop.mass) * (-prop.loss * (spt - oat));
    coolT.push(dt);
    coolTemp.push(spt);
    tChart.push({ time: dt*1000, temperature: utils.toFix(spt, 1), series: 'Building Cooling (pred.)' })
    tChart.push({ time: dt*1000, temperature: utils.toFix(oat, 1), series: 'Outside Air Temp. (pred.)' })
//    tChart.push({ time: dt, temperature: spt, series: 'Building Cooling' })
//    tChart.push({ time: dt, temperature: oat, series: 'Outside Air Temperature' })
    dt += dtStep;
    n -= 1
  }
  // Backward heating curve from opening time
  dt = prop.dtOpen;
  spt = prop.hsp;    // should using live temperature
  while (dt > dtStart && n) {
    const oat = oatFn(dt)
    spt -= (dtH / prop.mass) * (prop.power - prop.loss * (spt - oat));
    tChart.push({ time: dt*1000, temperature: utils.toFix(spt, 1), series: 'Building Warming (pred.)' })
    dt -= dtStep;
    const sptCool = interp(dt, coolT, coolTemp);
    if (spt <= sptCool) return dt; // curves meet: this is the start time
    n -= 1
  }
  return dtStart; // must start immediately / can't make it
}

function getLastLocaleTimeStamp(targetHour, dayCount, targetMinute = 0)
{
  const now = new Date();
  const targetDate = new Date();
  // 1. Set the target time for TODAY first
  targetDate.setHours(targetHour, targetMinute, 0, 0);

  // 2. Conditional check: If that time has already passed today, move to tomorrow
  {
    targetDate.setDate(targetDate.getDate() + dayCount);
  }
  // 3. Convert milliseconds to Unix seconds and store in msg.payload
  return Math.floor(targetDate.getTime() / 1000);
}


function getNextLocaleTimestamp(targetHour, targetMinute = 0) 
{
  const now = new Date();
  const targetDate = new Date();

  // 1. Set the target time for TODAY first
  targetDate.setHours(targetHour, targetMinute, 0, 0);

  // 2. Conditional check: If that time has already passed today, move to tomorrow
  if (now >= targetDate) {
    targetDate.setDate(targetDate.getDate() + 1);
  }
  // 3. Convert milliseconds to Unix seconds and store in msg.payload
  return Math.floor(targetDate.getTime() / 1000);
}


function getNextUtcTimestamp(hours, mins = 0) {

  const now = new Date(nowSecs * 1000)
  const target = new Date(Date.UTC(now.getUTCFullYear(),
    now.getUTCMonth(),
    now.getUTCDate(),
    hours, mins, 0, 0
  ));
  // If hours:mins UTC has already passed today, move to tomorrow
  if (now >= target) {
    target.setUTCDate(target.getUTCDate() + 1);
  }
  // Convert milliseconds to seconds (Unix timestamp)
  return Math.floor(target.getTime() / 1000);
}



// Linear interpolation (like numpy.interp): clamps outside the range.
// xs must be ascending.
function interp(x, xs, ys) {
  if (x <= xs[0]) return ys[0];
  const n = xs.length;
  if (x >= xs[n - 1]) return ys[n - 1];
  let i = 1;
  while (xs[i] < x) i++;
  const f = (x - xs[i - 1]) / (xs[i] - xs[i - 1]);
  return ys[i - 1] + f * (ys[i] - ys[i - 1]);
}

