/** 
 * Calculate flow temperature. 
 * This is the most important node.
 */


const utils = global.get("utils")


/**
* For a value of x between x1 to x2, find the value of y between y1 and y2
* Assume x y and have a linear relationship.
*/

function lookup(x, x1, x2, y1, y2) {
  // Calculate the slope (m)
  const slope = (y2 - y1) / (x2 - x1);

  // Calculate the y-intercept (b) using the point-slope form (y - y1 = m(x - x1))
  const yIntercept = y1 - slope * x1;

  // Calculate the y value for the given x
  const y = slope * x + yIntercept;

  return [utils.toFix(y, 1), utils.toFix(slope, 1)]
}


function calculateFlowTemperature(prop) {
  const oatBanded = Math.max(Math.min(prop.oat, prop.hrOatFull), prop.hrOatNone)
  //node.warn("band " + oatBanded);

  const res = lookup(oatBanded, prop.hrOatFull, prop.hrOatNone
    , prop.hrFlowFull, prop.hrFlowNone);

  const [wcTemp, wcSlope] = res

  // use v1 algorithm and hard coded range for now 

  const [lcTemp, lcSlope] = lookup(prop.pidOut, 0, 1, prop.lcLow, prop.lcHigh)

  const [trim, lcSlope1] = lookup(prop.pidOut, 0, 1, -prop.lcTrim, prop.lcTrim)

  // add the weather compensation and the load compensation (needs fixing)
  // to create Weather Compensation plus Trim

  const wctTemp = utils.toFix(wcTemp + trim, 1);

  let flowSetPoint = prop.hrEnabled ? wctTemp : lcTemp

  //node.error(` load comp ${lcTemp}  flowSetPoint ${flowSetPoint} `)

  flowSetPoint = Math.max(Math.min(flowSetPoint, prop.flowMax), prop.flowMin)

  return [wcTemp, lcTemp, trim, wctTemp, flowSetPoint]
}


function selectHeatSource(prop, flowSetPoint, status1, status2) {
  // any time there is any setting change, we still 
  // reconsider what heat source we 
  const log = []
  let heatSource = null       // this is how we set the LAE0 switch
  let off = ''
  const palette = {
    disengage: "purple",
    manual: "blue",
    off: "grey",
    auto: "purple",
    ashp: "green",
    gas: "red"
  }

  switch (prop.heatingMode) {

    case 'auto':
      const demand = prop.demand == 'heat-on'      // heat demanded
      const flowMinReached = flowSetPoint > prop.flowMin
      const currentHeatSource = flow.get('heatSource') ?? 'off'
      const reach = prop.hsp + (currentHeatSource == 'off' ? -prop.hys : prop.hys)
      const hspReached = prop.spt >= reach
      const flowGasReached = flowSetPoint > prop.flowGas
      heatSource = flowGasReached ? 'gas' : 'ashp'
      if (!demand) {
        log.push('Not scheduled to run')
        off = 'off'
      }
      else {
        if (flowGasReached) {
          if (hspReached) {
            log.push(`Heating setpoint reached`)
            off = 'off'
          }
        }
        else {
          if (!flowMinReached) {
            log.push('Requested flow temperature too low. Turn up Heating setpoint')
            off = 'off'
          }
        }
      }
      break
    case 'disengage':
      heatSource = 'disengage'
      log.push(`Disengaged: heat pump/gas boiler will remain stopped or running regardless of schedule or temperatures `)
      break
    case 'gas':
      log.push('Gas boiler will stay running regardless of clock and temperatures')
      heatSource = prop.heatingMode
      break
    case 'ashp':
      log.push('ASHP will stay running regardless of clock and temperatures. Flow temperature will still be adjusted.')
      heatSource = prop.heatingMode
      break
    case 'off':
      heatSource = prop.heatingMode
      break
  }
  prop.heatingModeHelp = log.join(' ')

  //let texxt1 = `<div style="text-align:right; padding:0.3em; border-radius:0.5em; font-weight:normal; font-size:1.8em; background-color:${palette[heatSource]};color:white;">${heatSource} ${off}</div>`
  let texxt1 = `<div style="text-align:center; padding:0.3em; border-radius:0.5em; font-weight:normal; font-size:1.7em; background-color:${palette[heatSource]};color:white; width:5em; height:100%;">${heatSource} ${off}</div>`

  //texxt1 = `${heatSource} ${off}`

  let texxt2 = log.join(' ')
  texxt2 = texxt2 ? `<div style="text-align:left;">${utils.getHHMMNow()} ${texxt2}</div>` : ''
  status2.unshift(texxt2)



  status1.unshift(texxt1)

  return off ? 'off' : heatSource
}

function doCalculation(settings, ashpControl, switchControl, notices) {
  const [weatherComp, loadComp, trim, weatherPlusTrim, flowSetPoint] = calculateFlowTemperature(settings)
  const status1 = []
  const status2 = []
  const heatSource = selectHeatSource(settings, flowSetPoint, status1, status2)

  ashpControl.push({
    topic: 'ashp0/SETPOINT_hsp1',
