    PID: utils.toFix(settings.pidOut, 2),
    //    lcLow: settings.lcLow,  
    //    lcHigh: settings.lcHigh, 
    lc: loadComp,
    trim: trim,
    wct: weatherPlusTrim,
    dem: settings.demand,
    hs: heatSource,
    min: settings.flowMin,
    gas: settings.flowGas,
    max: settings.flowMax,
    wat: flowSetPoint
  }

  notices.push({
    topic: 'log/record/joule0',
    payload: calcs,
    timestamp: Date.now(),
    prefix: 'local',
    param: 'control',   // for influx
    //source: 'joule0'
  })

  notices.push({
    topic: 'joule0/status1',
    payload: status1,
    prefix: 'local'
  })

  notices.push({
    topic: 'joule0/status2',
    payload: status2,
    prefix: 'local'
  })


  const logText = [
    `hm:${settings.heatingMode}`,
    `oat:${settings.oat} wc:${weatherComp}`,
