const controlOf = (target, payload, delay = 1) => ({
  topic:       target,
  param:      'state',
  payload:     payload,
  delay:       delay
})

let ashpControl = []
let switchControl = []
let notices = []

function changeHeatSource(currentHeatSource, heatSource, ashpControl, switchControl,  notices) 
{
  // override the preset LAE0 temperatures to force 
  // the controller into the required heating mode 

  let pumpOverrun = false 

  switch(heatSource) {
    case 'off' :   // heating off, low band 
      if (currentHeatSource == 'off')
        break 

      ashpControl.push(controlOf('PROTOCOL_CHIL_S_S', 0)) 
      pumpOverrun =  (currentHeatSource == 'ashp');
      const delay = (pumpOverrun ? 60 : 1) * 1000  ;
      switchControl.push({
        topic: 'lae0/1SP',
        payload: 0.5,
        delay: delay
      })  
      switchControl.push({
        topic: 'lae0/2SP',
        payload: 1.5,
        delay: delay
      })
      break ;

    case 'ashp':   // ASHP on, wide band 
      if (currentHeatSource == 'ashp')
        break 

      ashpControl.push(controlOf('PROTOCOL_CHIL_S_S', 1)) 
      switchControl.push({
        topic: 'lae0/1SP',
        payload: 0.5,
      })  
      switchControl.push({
        topic: 'lae0/2SP',
        payload: 18.5,
      }) 
      break  

    case 'gas' :   // gas on, high band 
      if (currentHeatSource == 'gas')
        break

      ashpControl.push(controlOf('PROTOCOL_CHIL_S_S', 0))   
      switchControl.push({
        topic: 'lae0/1SP',
        payload: 17.5,
      }) 
      switchControl.push({
        topic: 'lae0/2SP',
        payload: 18.5,
      })        
      break  


    default : 
      node.error("Unrecognised heat source", heatSource);
      switchControl.push({
        topic: 'lae0/1SP',
        payload: 5,
      })
      switchControl.push({
        topic: 'lae0/2SP',
        payload: 18,
      })
      return null ;
  }

  const heatSourceColour = { off: 'yellow', ashp: 'green', gas: 'red'}
  const mode = `${currentHeatSource}->${heatSource}` 
  const logText = pumpOverrun ? `${mode} ${pumpOverrun}` : `${mode}`  
  node.status({
    fill: heatSourceColour[heatSource], shape: "dot",
    text: `${utils.getTimeNow()} ${logText}`
  })
  const status = []
  status.unshift(`${utils.getHHMMNow()} ${logText}`)

  // new
  /*
  const status = []
  const log = []
  const heatSourceColour = { off: 'yellow', ashp: 'green', gas: 'red' }
  const mode = `${currentHeatSource}->${heatSource}`
  log.push(mode)
  pumpOverrun ? log.push('pump overrun') : null
  node.status({
    fill: heatSourceColour[heatSource], shape: "dot",
    text: `${utils.getTimeNow()} ${log.join(" ")}`
  })
  status.unshift({ hhmm: utils.getHHMMNow(), mode: mode, comment: log.join(" ") })
  */


  //    notices.push(noticeOf(settings, subTopic))

  notices.push({
    topic: 'joule0/status3',
    payload: status,
    prefix: 'local'
  })


  notices.push({
    topic:      'joule0/log',
    payload:     `${utils.getTimeNow()} ${logText}`, 
    prefix:      'local'
  })

}

if (msg.topic != 'joule0/heatSource')
{
  node.error(`Received ${msg.topic}, expect only switch/heatSource`, msg);
  return null ;
}

const currentHeatSource = flow.get('heatSource') ?? 'off' 
const futureHeatSource = msg.payload ;
const pumpOverrun = changeHeatSource(currentHeatSource, futureHeatSource, ashpControl, switchControl,  notices)
flow.set('heatSource', futureHeatSource)

return [ashpControl, switchControl,  notices]

