function lookupRegister(subTopic) {
    const registers = flow.get("modbusRegistersLAE0");
    for (const row of registers) {
        if (row["Mnem."] == subTopic)
            return row;
    }
    node.error('Unable to find register in map ' + subTopic)
    return null;
}

