function swapEndian(xb) {
    return [xb[1], xb[0], xb[3], xb[2]]
}

function float32ToBytes(fl) {
    const f32 = new Float32Array(1); f32[0] = fl;
    const ui8 = new Uint8Array(f32.buffer);
    return swapEndian((Array.from(ui8)));
}

// this still works on incoming data
