function collectData(msg) {
  const tokens = msg.topic.split("/")
  const sensorName = tokens[0]
  const sensorProperty = tokens[1]

  let m = null

  if (["PUMPSTAT_CAPPOWER", "zeroCounters"].includes(sensorProperty)) 
