    switch (sensorProperty) {
      case "PUMPSTAT_CAPPOWER":
        //node.error('hhh II ' + msg.topic + " " + sensorProperty + " " + history['ashp0/today/kWh'] ?? 0)

        let avg = integral("PUMPSTAT_CAPPOWER", Number(msg.payload))
        let elapsedHours = history["PUMPSTAT_CAPPOWER"].e / (1000 * 3600)
        let kWh = avg * elapsedHours
        history['ashp0/today/kWh'] = kWh // save to move to yesterday
        m = {
          topic: `ashp0/today/kWh`,  // update on each kWh consumed
          param: 'kWh',
          prefix : 'local',  
          payload: Math.floor(kWh),
          source: 'ashp0',
          digest: false,
          track: false
        }                // send update for each kWh
        break

      case "zeroCounters":

        node.status({ fill: "yellow", shape: "dot", text: `midnight : counter reset` });

        history['ashp0/yesterday/kWh'] = history['ashp0/today/kWh']
        zeroIntegral("PUMPSTAT_CAPPOWER")

        m = {
          topic: `ashp0/yesterday/kWh`,
          param:    'kWh',
          prefix : 'local',   
          payload: Math.floor(history['ashp0/yesterday/kWh']),
          source: 'ashp0',
          digest: false,
          track: false
        }
        break
    }
  }
  return m
}


