/**
 * handle requests for sensor messsage recalls
 */


function handleMessage(msg, instrumentation)
{
  if (msg.topic === undefined) 
    node.red(msg.payload)

  switch(msg.topic)
  {
    case 'app/request/refresh' :
    case 'get/all' :
      // strip out the keys
      let ar = Object.values(instrumentation)
      node.status({ fill: "green", shape: "dot", text: `fetched ${ar.length} items`});
      // and replay the stream of messages
      return [] ;
      return ar  ;

    case 'clear' :
      context.set("instrumentation", {});
      node.status({ fill: "green", shape: "dot", text: `instrumentation cleared`})
      return [] ;

    default :
      if (isValidMessage(msg, instrumentation))
      {
        instrumentation[msg.topic] = msg;
        context.set('instrumentation', instrumentation)
      }
      return []
  }
}


// don't store items that are not objects

function isValidMessage(msg, instrumentation)
{
  //node.error('abc', msg)
  if (typeof msg !== 'object')
  {
    node.status({ fill: "red", shape: "triange", text: `rejecting ${msg.topic}, not an object` });
    return false ;
  }

  if (msg.payload === undefined)
  {
    node.status({ fill: "red", shape: "triange", text: `rejecting ${msg.topic}, no payload` });
    return false ;
  }

  if (!msg.timestamp)
    msg.timestamp = Date.now()

  return true ;
}

