const timeNow = Date.now()
const siteConfig = global.get('site-config') ?? {}
const instrumentation = flow.get("instrumentation") ?? {}
const utils = global.get('utils')

const sensorWeight =
  [
    { name: 'g3', weight: 1 }, // main entrance 
    { name: 'g4', weight: 1 }, // cu ground
    { name: 'm0', weight: 2 }, // first floor corridor
    { name: 'm3', weight: 1 }, // cu front
  ]


// need to move this out to app node that calculate this

function calculateBuildingTemperature(instruments, minsTimeout) 
{ 
  const sensorsKnown = Object.keys(siteConfig['sensorMap'])
  // note messages are stored in instruments
  // make instrument temperatures easier to access
  const sensorTemp = ((name) => instruments[name + '/temperature'].payload)

  const sensorsReport = utils.sensorStatus(sensorsKnown, instruments, minsTimeout, timeNow)

  const sensors = sensorWeight
    // filter the sensorWeight table so only online sensors included
    .filter((w) => (sensorsReport['online'].includes(w.name)))

    // create new map of weighted temperatures
    .map((e) => ({  name: e.name, 
                    t: sensorTemp(e.name), 
                    wt: sensorTemp(e.name) * e.weight, w: e.weight 
                }))
    // filter out suspect values
    //.filter((e) => 16 < e.t && e.t < 23 && e.t != 22)

  const sensorIDs = sensors.map((e) => e.name).join(",")

  // calculate weighted average
  const buildingTemperature = sensors.reduce((sum, e, idx) => (sum + e.wt), 0)
    / sensors.reduce((sum, e, idx) => (sum + e.w), 0)

  node.status({
    fill: "yellow", shape: "dot",
    text: `${utils.getHHMM(timeNow)} b0:${buildingTemperature.toFixed(1)} [${sensorIDs}]`
  });
  return buildingTemperature
}

/**
* @param {NodeMessage} msg
*/

function processUpdates(msg) 
{
  const tokens = msg.topic.split("/")
  const sensorName = tokens[0]
  const sensorProperty = tokens[1]

  let b0 = null
  let setpoint1 = null 
  let setpoint2 = null 

  const sensorsSelected = sensorWeight.map((e) => e.name)
  if (sensorsSelected.includes(sensorName)) 
    if (['temperature'].includes(sensorProperty)) 
  {
    const bt = calculateBuildingTemperature(instrumentation, 31)

    // create a virtual sensor 
    b0 = {
      topic:        'b0/temperature',
      source:       'b0',
      location:     'building',
      payload:      Math.round(100 * bt) / 100, // update on 0.01 increments
      bt0:          Math.round(100 * bt) / 100, // update on 0.01 increments
      param:        'temperature',  // needed for influx
      digest:       true,
      prefix:       'local',        // pretend to be a sensor, albeit virtual, so influx stores
      reportOnDiff: 0.1,            
      windowPeriodSecs: 15 * 60 ,   // report every 10 minutes regardless
      track: true                   // update status text under node
    }
    b0 = isNaN(bt) ? null : b0 ;
  }
  return b0
}

const msgs = processUpdates(msg)
